INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31561, 'Nehemiah 12:42', 'Nehemiah', 12, 42, 'معسیا، شمعیه، العازار، عزي، یوحانان، ملکیا، عیلام او ایصر د هغوی پسې روان وو. هغو سندرغاړو چې د یزرحیا له خوا یې لارښوونه کېدله، په لوړ اواز سره سندرې ویلې.', 'معسیا، شمعیه، العازار، عزی، یوحانان، ملکیا، عیلام او ایصر د هغوی پسې روان وو. هغو سندرغارو چې د یزرحیا له خوا یې لارشوونه کېدله، په لور اواز سره سندرې ویلې.', 'OT', 'afghan2023', 'afghan', '', '', 1761237836, 1761237836),
(31562, 'Nehemiah 12:43', 'Nehemiah', 12, 43, 'په هغه ورځ ډېرې قربانۍ وړاندې شوې او خلک د خپلو ښځو او ماشومانو سره خوشحاله وو، ځکه چې خدای د هغوی زړونه د خوشحالۍ څخه ډک کړي وو. د اورشلیم د خلکو د خوشحالۍ اواز له ډېر لېرې ځای څخه اورېدل کېده.', 'په هغه ورج دېرې قربانی وراندې شوې او خلک د خپلو شجو او ماشومانو سره خوشحاله وو، جکه چې خدای د هغوی زرونه د خوشحالی چخه دک کری وو. د اورشلیم د خلکو د خوشحالی اواز له دېر لېرې جای چخه اورېدل کېده.', 'OT', 'afghan2023', 'afghan', '', '', 1761237836, 1761237836),
(31563, 'Nehemiah 12:44', 'Nehemiah', 12, 44, 'په هغه ورځ ځینې خلک د ګودامونو د مسوولانو په توګه وټاکل شول چې په هغو کې به د خدای د کور دپاره اعانې، د حاصلاتو لسمه برخه او لومړنۍ غلې دانې او مېوې چې هر کال به پخېدلې، ساتل کېدلې. دې مسوولانو دا دنده درلودله چې د هغو کروندو څخه چې ښارونو ته نژدې وې، د کاهنانو او لاویانو برخه د شریعت د اصولو سره سم راټوله کړي. د یهودا ټول خلک د کاهنانو او لاویانو د خدمت څخه خوشحاله وو،', 'په هغه ورج جینې خلک د ګودامونو د مسوولانو په توګه وتاکل شول چې په هغو کې به د خدای د کور دپاره اعانې، د حاصلاتو لسمه برخه او لومرنی غلې دانې او مېوې چې هر کال به پخېدلې، ساتل کېدلې. دې مسوولانو دا دنده درلودله چې د هغو کروندو چخه چې شارونو ته نژدې وې، د کاهنانو او لاویانو برخه د شریعت د اصولو سره سم راتوله کری. د یهودا تول خلک د کاهنانو او لاویانو د خدمت چخه خوشحاله وو،', 'OT', 'afghan2023', 'afghan', '', '', 1761237836, 1761237836),
(31564, 'Nehemiah 12:45', 'Nehemiah', 12, 45, 'ځکه چې هغوی د پاکوالي مراسم او هغه نورې دندې سرته رسولې چې خدای د هغو حکم کړی ؤ. د خدای د کور سندرغاړو او ساتونکو هم خپلې دندې د داود پاچا او د هغه د زوی سلیمان د حکم سره سم تر سره کولې.', 'جکه چې هغوی د پاکوالی مراسم او هغه نورې دندې سرته رسولې چې خدای د هغو حکم کری و. د خدای د کور سندرغارو او ساتونکو هم خپلې دندې د داود پاچا او د هغه د زوی سلیمان د حکم سره سم تر سره کولې.', 'OT', 'afghan2023', 'afghan', '', '', 1761237836, 1761237836),
(31565, 'Nehemiah 12:46', 'Nehemiah', 12, 46, 'په پخوا زمانه کې، یعنې د داود او اساف په زمانه کې د سندرغاړو او خدای ته د شکرګزارۍ او ثنا ویلو د سندرو دپاره لارښوونکي موجود وو.', 'په پخوا زمانه کې، یعنې د داود او اساف په زمانه کې د سندرغارو او خدای ته د شکرګزاری او ثنا ویلو د سندرو دپاره لارشوونکی موجود وو.', 'OT', 'afghan2023', 'afghan', '', '', 1761237836, 1761237836),
(31566, 'Nehemiah 12:47', 'Nehemiah', 12, 47, 'د زروبابل او نحمیا په زمانه کې به د اسراییلو ټولو خلکو هره ورځ د خدای د کور سندرغاړو او ساتونکو ته خواړه او نور د اړتیا وړ شیان ورکول. خلکو به لاویانو ته سپېڅلې نذرانې ورکولې او لاویانو به کاهنانو ته د اړتیا وړ برخه ورکوله.', 'د زروبابل او نحمیا په زمانه کې به د اسراییلو تولو خلکو هره ورج د خدای د کور سندرغارو او ساتونکو ته خواره او نور د ارتیا ور شیان ورکول. خلکو به لاویانو ته سپېچلې نذرانې ورکولې او لاویانو به کاهنانو ته د ارتیا ور برخه ورکوله.', 'OT', 'afghan2023', 'afghan', '', '', 1761237836, 1761237836),
(31567, 'Lamentations 5:1', 'Lamentations', 5, 1, 'اے مالِکه خُدايه، راياد کړه چې په مونږ څۀ وشو، وګوره چې زمونږ څنګه بې‌عزتى شوې ده.', 'اے مالکه خدایه، رایاد کره چې په مونز چۀ وشو، وګوره چې زمونز چنګه بې‌عزتی شوې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31568, 'Lamentations 5:2', 'Lamentations', 5, 2, 'زمونږ ميراث غېرو ته حواله شوے دے او زمونږ کورونه پردو خلقو قبضه کړى دى.', 'زمونز میراث غېرو ته حواله شوے دے او زمونز کورونه پردو خلقو قبضه کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31569, 'Lamentations 5:3', 'Lamentations', 5, 3, 'مونږ يتيمان او بې‌پلاره شوى يُو او زمونږ ميندې کونډې شوې دى.', 'مونز یتیمان او بې‌پلاره شوی یو او زمونز میندې کوندې شوې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31570, 'Lamentations 5:4', 'Lamentations', 5, 4, 'مونږ د څښلو اوبۀ او د سوزولو خشاک په بيعه اخلو.', 'مونز د چشلو اوبۀ او د سوزولو خشاک په بیعه اخلو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31571, 'Lamentations 5:5', 'Lamentations', 5, 5, 'هغوئ څوک چې مونږ پسې وُو راته په سر ناست دى او مونږ ډېر ستومانه شُو خو هيڅ آرام ته مو نۀ پرېږدى.', 'هغوی چوک چې مونز پسې وو راته په سر ناست دی او مونز دېر ستومانه شو خو هیچ ارام ته مو نۀ پرېزدی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31572, 'Lamentations 5:6', 'Lamentations', 5, 6, 'مونږ خپل ځان مِصر او اسور ته حواله کړو چې مونږ ته پوره روټۍ مِلاو شى.', 'مونز خپل جان مصر او اسور ته حواله کرو چې مونز ته پوره روتی ملاو شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31573, 'Lamentations 5:7', 'Lamentations', 5, 7, 'زمونږ پلار نيکۀ ګناه وکړه خو هغوئ مړۀ دى او اوس مونږ د هغوئ د ګناه سزا خورو.', 'زمونز پلار نیکۀ ګناه وکره خو هغوی مرۀ دی او اوس مونز د هغوی د ګناه سزا خورو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31574, 'Lamentations 5:8', 'Lamentations', 5, 8, 'غلامان په مونږ حکومت کوى او هيڅ څوک نشته چې مونږ د هغوئ د لاس نه آزاد کړى.', 'غلامان په مونز حکومت کوی او هیچ چوک نشته چې مونز د هغوی د لاس نه ازاد کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31575, 'Lamentations 5:9', 'Lamentations', 5, 9, 'مونږ د روټۍ پېدا کولو دپاره خپل ځان په خطره کښې اچولے دے ځکه چې په ټوله علاقه کښې وسله وال ګرځى.', 'مونز د روتی پېدا کولو دپاره خپل جان په خطره کشې اچولے دے جکه چې په توله علاقه کشې وسله وال ګرجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31576, 'Lamentations 5:10', 'Lamentations', 5, 10, 'زمونږ څرمن لکه د تنور په شان ګرمه ده، د قحط د ډېر تاو نه سوزېدلې ده.', 'زمونز چرمن لکه د تنور په شان ګرمه ده، د قحط د دېر تاو نه سوزېدلې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31577, 'Lamentations 5:11', 'Lamentations', 5, 11, 'په صيون کښې د ښځو عزت لوټ شوے دے او د يهوداه په ښارونو کښې د پېغلو عزت لوټ شوے دے.', 'په صیون کشې د شجو عزت لوت شوے دے او د یهوداه په شارونو کشې د پېغلو عزت لوت شوے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31578, 'Lamentations 5:12', 'Lamentations', 5, 12, 'دوئ شهزادګان د لاسونو نه راځوړند کړى دى او د مشرانو بې‌عزتى يې کړې ده.', 'دوی شهزادګان د لاسونو نه راجورند کری دی او د مشرانو بې‌عزتی یې کرې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31579, 'Lamentations 5:13', 'Lamentations', 5, 13, 'په ځوانانو په زور مېچنې ګرځولے شى، او زلمى د لرګو د درنو بارونو لاندې په تکليف روان دى.', 'په جوانانو په زور مېچنې ګرجولے شی، او زلمی د لرګو د درنو بارونو لاندې په تکلیف روان دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31580, 'Lamentations 5:14', 'Lamentations', 5, 14, 'مشرانو د ښار په دروازه د جرګو ځايونه پرېښودل او ځوانانو خپل ساز و سرود پرېښودو.', 'مشرانو د شار په دروازه د جرګو جایونه پرېشودل او جوانانو خپل ساز و سرود پرېشودو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31581, 'Lamentations 5:15', 'Lamentations', 5, 15, 'زمونږ د زړۀ خوشحالى رانه اخستے شوې ده او زمونږ ګډا په ماتم بدله شوې ده.', 'زمونز د زرۀ خوشحالی رانه اخستے شوې ده او زمونز ګدا په ماتم بدله شوې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31582, 'Lamentations 5:16', 'Lamentations', 5, 16, 'زمونږ نه تاج و تخت اخستلے شوے دے، افسوس په مونږ ځکه چې مونږ ګناه کړې ده.', 'زمونز نه تاج و تخت اخستلے شوے دے، افسوس په مونز جکه چې مونز ګناه کرې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31583, 'Lamentations 5:17', 'Lamentations', 5, 17, 'ځکه د دې په وجه زمونږ زړونه مات شوى دى او د ژړا په وجه زمونږ نظر کم شوے دے.', 'جکه د دې په وجه زمونز زرونه مات شوی دی او د ژرا په وجه زمونز نظر کم شوے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31584, 'Lamentations 5:18', 'Lamentations', 5, 18, 'دا چې د صيون غر وران ويجاړ پروت دے او ګيدړان په کښې اوسيږى.', 'دا چې د صیون غر وران ویجار پروت دے او ګیدران په کشې اوسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31585, 'Lamentations 5:19', 'Lamentations', 5, 19, 'خو تۀ اے مالِکه خُدايه، د تل دپاره حکومت کوې او ستا تخت په ټولو نسلونو کښې قائم پاتې کيږى.', 'خو تۀ اے مالکه خدایه، د تل دپاره حکومت کوې او ستا تخت په تولو نسلونو کشې قایم پاتې کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31586, 'Lamentations 5:20', 'Lamentations', 5, 20, 'تا ولې مونږ بلکل هېر کړى يُو؟ تا ولې مونږ ډېرو ورځو نه پرېښى يُو؟', 'تا ولې مونز بلکل هېر کری یو؟ تا ولې مونز دېرو ورجو نه پرېشی یو؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31587, 'Lamentations 5:21', 'Lamentations', 5, 21, 'اے مالِکه خُدايه مونږ ځان ته راوبله، مونږ بحال کړه او زمونږ حال د مخکښې په شان کړه.', 'اے مالکه خدایه مونز جان ته راوبله، مونز بحال کره او زمونز حال د مخکشې په شان کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31588, 'Lamentations 5:22', 'Lamentations', 5, 22, 'ولې تا مونږ تل دپاره رد کړى يُو؟ او تۀ مونږ ته د حد نه زيات غصه يې؟', 'ولې تا مونز تل دپاره رد کری یو؟ او تۀ مونز ته د حد نه زیات غصه یې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_5_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
